"""Scan a PDF for hidden text: white/near-white color, tiny fonts, off-page,
invisible render mode, annotations, metadata, embedded files, JS, optional layers."""
import sys
import pymupdf

path = sys.argv[1]
doc = pymupdf.open(path)

print("== METADATA ==")
for k, v in doc.metadata.items():
    print(f"  {k}: {v!r}")
print("  pages:", doc.page_count)
print("  embedded files:", doc.embfile_names())
print("  optional content (layers):", doc.layer_ui_configs() if hasattr(doc, "layer_ui_configs") else "n/a")
try:
    print("  xml metadata:", (doc.get_xml_metadata() or "")[:500])
except Exception as e:
    print("  xml metadata err:", e)

# Look for JavaScript / suspicious keys in raw objects
sus = []
for xref in range(1, doc.xref_length()):
    try:
        obj = doc.xref_object(xref)
    except Exception:
        continue
    for key in ("/JavaScript", "/JS", "/OpenAction", "/AA", "/Launch", "/EmbeddedFile", "/OCG"):
        if key in obj:
            sus.append((xref, key))
print("  suspicious object keys:", sus or "none")


def lum(c):
    r, g, b = (c >> 16) & 255, (c >> 8) & 255, c & 255
    return (0.299 * r + 0.587 * g + 0.114 * b) / 255


print("\n== HIDDEN-TEXT CHECKS ==")
flags_found = 0
for pno, page in enumerate(doc, 1):
    rect = page.rect
    d = page.get_text("rawdict", flags=pymupdf.TEXT_PRESERVE_WHITESPACE)
    for b in d["blocks"]:
        for l in b.get("lines", []):
            for s in l["spans"]:
                text = "".join(ch["c"] for ch in s.get("chars", []))
                if not text.strip():
                    continue
                reasons = []
                if lum(s["color"]) > 0.85:
                    reasons.append(f"light color #{s['color']:06x}")
                if s["size"] < 4:
                    reasons.append(f"tiny font {s['size']:.1f}")
                bb = pymupdf.Rect(s["bbox"])
                if not bb.intersects(rect):
                    reasons.append("off-page")
                if s.get("alpha", 255) < 50:
                    reasons.append(f"alpha {s.get('alpha')}")
                if reasons:
                    flags_found += 1
                    print(f"  p{pno} [{', '.join(reasons)}] {text!r}")
    # invisible render mode (Tr 3) via trace
    for t in page.get_texttrace():
        if t.get("type") == 3 or t.get("opacity", 1) < 0.2:
            txt = "".join(chr(c[0]) for c in t["chars"])
            if txt.strip():
                flags_found += 1
                print(f"  p{pno} [render-type {t.get('type')} opacity {t.get('opacity')}] {txt!r}")
    for a in page.annots() or []:
        print(f"  p{pno} annotation {a.type}: {a.info}")
    for ln in page.get_links():
        print(f"  p{pno} link: {ln.get('uri') or ln}")
print("  flagged spans:", flags_found)

print("\n== FULL TEXT ==")
for pno, page in enumerate(doc, 1):
    print(f"\n--- page {pno} ---")
    print(page.get_text())

# Zero-width / unusual unicode
import unicodedata
alltext = "".join(p.get_text() for p in doc)
odd = {c for c in alltext if unicodedata.category(c) in ("Cf", "Co", "Cn")}
print("\n== UNUSUAL UNICODE ==", [hex(ord(c)) for c in odd] or "none")
print("images per page:", [len(p.get_images()) for p in doc])

