// without keeping its own copy of the rules.
function allowedActions(status) {
  return Object.keys(ACTIONS).filter((action) => canTransition(status, ACTIONS[action]));
}

module.exports = {
  TRANSITIONS,
  ACTIONS,
  ACTIVE_STATUSES,
  canTransition,
  assertTransition,
  allowedActions,
};

