const { calculateScore, rankOrders } = require('../src/modules/priority');

// Frozen clock: every test uses this `now`, never Date.now().
const NOW = new Date('2026-06-15T12:00:00Z');
const minutesAgo = (minutes) => new Date(NOW.getTime() - minutes * 60 * 1000);
const minutesFromNow = (minutes) => new Date(NOW.getTime() + minutes * 60 * 1000);

// A baseline order worth exactly 30 points (dine_in, nothing else), so each test
// changes one input and checks one component.
function makeOrder(overrides = {}) {
  return {
    id: 1,
    type: 'dine_in',
    is_vip: false,
    placed_at: NOW,
    promised_at: null,
    items: [{ prep_time_minutes: 5, quantity: 1 }],
    ...overrides,
  };
}

describe('calculateScore: spec worked examples', () => {
  const exampleA = makeOrder({
    id: 1,
    placed_at: new Date('2026-06-15T11:25:00Z'),
    items: [
      { prep_time_minutes: 20, quantity: 2 }, // Grilled Salmon
      { prep_time_minutes: 10, quantity: 1 }, // Caesar Salad
    ],
  });
  const exampleB = makeOrder({
    id: 2,
    type: 'delivery',
    is_vip: true,
    placed_at: new Date('2026-06-15T11:50:00Z'),
    promised_at: new Date('2026-06-15T12:20:00Z'),
    items: [{ prep_time_minutes: 12, quantity: 1 }], // Margherita Pizza
  });

  test('example A scores 60', () => {
    expect(calculateScore(exampleA, NOW)).toBe(60);
  });

  test('example B scores 60', () => {
    expect(calculateScore(exampleB, NOW)).toBe(60);
  });

  test('B ranks above A on the promised_at tie-break', () => {
    const ranked = rankOrders([exampleA, exampleB], NOW);
    expect(ranked.map((o) => o.id)).toEqual([2, 1]);
    expect(ranked.map((o) => o.score)).toEqual([60, 60]);
  });
});

describe('calculateScore: order type and VIP', () => {
  test.each([
    ['dine_in', 30],
    ['takeout', 20],
    ['delivery', 10],
  ])('%s base is %i points', (type, points) => {
    expect(calculateScore(makeOrder({ type }), NOW)).toBe(points);
  });

  test('VIP adds 20 points', () => {
    expect(calculateScore(makeOrder({ is_vip: true }), NOW)).toBe(50);
  });
});

describe('calculateScore: wait time', () => {
  test('uses whole minutes: 9m50s is 9 minutes, so 0 points', () => {
    const placedAt = new Date(NOW.getTime() - (9 * 60 + 50) * 1000);
    expect(calculateScore(makeOrder({ placed_at: placedAt }), NOW)).toBe(30);
  });

  test('10 minutes gives 5 points', () => {
    expect(calculateScore(makeOrder({ placed_at: minutesAgo(10) }), NOW)).toBe(35);
  });

  test('reaches the 40 point cap at 80 minutes', () => {
    expect(calculateScore(makeOrder({ placed_at: minutesAgo(80) }), NOW)).toBe(70);
  });

  test('is capped at 40 points for very old orders', () => {
    expect(calculateScore(makeOrder({ placed_at: minutesAgo(600) }), NOW)).toBe(70);
  });
});

describe('calculateScore: complexity', () => {
  test('14 prep minutes gives 0 points', () => {
    const items = [{ prep_time_minutes: 7, quantity: 2 }];
    expect(calculateScore(makeOrder({ items }), NOW)).toBe(30);
  });

  test('uses prep_time * quantity: 3 x 5 = 15 minutes gives 5 points', () => {
    const items = [{ prep_time_minutes: 5, quantity: 3 }];
    expect(calculateScore(makeOrder({ items }), NOW)).toBe(35);
  });

  test('is capped at 20 points', () => {
    const items = [{ prep_time_minutes: 45, quantity: 4 }]; // 180 min -> 60 raw points
    expect(calculateScore(makeOrder({ items }), NOW)).toBe(50);
  });
});

describe('calculateScore: promised time buckets', () => {
  test.each([
    ['null', null, 0],
    ['in 10 minutes', minutesFromNow(10), 25],
    ['exactly 30 minutes away', minutesFromNow(30), 25],
    ['30m30s away (just past the 30 minute bucket)', minutesFromNow(30.5), 15],
    ['in 45 minutes', minutesFromNow(45), 15],
    ['exactly 60 minutes away', minutesFromNow(60), 15],
    ['in 61 minutes', minutesFromNow(61), 0],
    ['in 3 hours', minutesFromNow(180), 0],
    ['already overdue', minutesAgo(5), 25],
  ])('%s gives %i points', (_label, promisedAt, points) => {
    expect(calculateScore(makeOrder({ promised_at: promisedAt }), NOW)).toBe(30 + points);
  });
});

describe('rankOrders', () => {
  test('a delivery VIP with a tight promise beats a dine_in non-VIP', () => {
    const dineIn = makeOrder({ id: 1, type: 'dine_in' }); // 30
    const deliveryVip = makeOrder({
      id: 2,
      type: 'delivery',
      is_vip: true,
      promised_at: minutesFromNow(15),
    }); // 10 + 20 + 25 = 55

    const ranked = rankOrders([dineIn, deliveryVip], NOW);

    expect(ranked.map((o) => o.id)).toEqual([2, 1]);
  });

  test('sorts by score, highest first', () => {
    const low = makeOrder({ id: 1, type: 'delivery' });
    const high = makeOrder({ id: 2, type: 'dine_in', is_vip: true });
    const mid = makeOrder({ id: 3, type: 'takeout' });

    expect(rankOrders([low, high, mid], NOW).map((o) => o.score)).toEqual([50, 20, 10]);
  });

  describe('tie-break on equal scores', () => {
    // All three promises are beyond 60 minutes, so they add 0 points and scores stay equal.
    test('earlier promised_at first, null last', () => {
      const noPromise = makeOrder({ id: 1, promised_at: null });
      const later = makeOrder({ id: 2, promised_at: minutesFromNow(120) });
      const earlier = makeOrder({ id: 3, promised_at: minutesFromNow(90) });

      expect(rankOrders([noPromise, later, earlier], NOW).map((o) => o.id)).toEqual([3, 2, 1]);
    });

    test('then earlier placed_at first', () => {
      // 1 and 2 minutes ago both give 0 wait points
      const newer = makeOrder({ id: 1, placed_at: minutesAgo(1) });
      const older = makeOrder({ id: 2, placed_at: minutesAgo(2) });

      expect(rankOrders([newer, older], NOW).map((o) => o.id)).toEqual([2, 1]);
    });

    test('then smaller id first', () => {
      const orders = [makeOrder({ id: 9 }), makeOrder({ id: 4 }), makeOrder({ id: 7 })];

      expect(rankOrders(orders, NOW).map((o) => o.id)).toEqual([4, 7, 9]);
    });
  });

  test('does not mutate the input array', () => {
    const orders = [makeOrder({ id: 2 }), makeOrder({ id: 1 })];
    rankOrders(orders, NOW);
    expect(orders.map((o) => o.id)).toEqual([2, 1]);
    expect(orders[0].score).toBeUndefined();
  });
});

// In-memory stand-in for src/repositories/orderRepository.js, with the same functions.
// Lets module tests run without Postgres and without mocking Sequelize.
function createFakeOrderRepository(initialOrders = [], menuItemIds = []) {
  const orders = initialOrders.map((order) => ({ ...order }));

  return {
    orders,

    async findByStatuses(statuses) {
      return orders.filter((order) => statuses.includes(order.status)).map((order) => ({ ...order }));
    },

    async findById(id) {
      const order = orders.find((o) => o.id === id);
      return order ? { ...order } : null;
    },

    async updateStatus(id, fromStatus, toStatus) {
      const order = orders.find((o) => o.id === id && o.status === fromStatus);
      if (!order) return false;
      order.status = toStatus;
      return true;
    },

    async findExistingMenuItemIds(ids) {
      return ids.filter((id) => menuItemIds.includes(id));
    },

    async create(order, items) {
      const id = orders.length + 1;
      orders.push({ id, ...order, items });
      return id;
    },
  };
}

module.exports = { createFakeOrderRepository };

const { TRANSITIONS, canTransition, assertTransition, allowedActions } = require('../src/modules/orderStatus');
const { createOrderModule } = require('../src/modules/orderModule');
const { createFakeOrderRepository } = require('./fakeOrderRepository');

const NOW = new Date('2026-06-15T12:00:00Z');
const ALL_STATUSES = Object.keys(TRANSITIONS);

function makeOrder(id, status) {
  return {
    id,
    customer_name: `Customer ${id}`,
    type: 'dine_in',
    is_vip: false,
    status,
    placed_at: NOW,
    promised_at: null,
    items: [{ menu_item_id: 1, name: 'Soup', prep_time_minutes: 5, quantity: 1 }],
  };
}

describe('state machine rules', () => {
  const legal = [
    ['received', 'preparing'],
    ['received', 'cancelled'],
    ['preparing', 'ready'],
    ['ready', 'picked_up'],
  ];

  test.each(legal)('%s -> %s is allowed', (from, to) => {
    expect(() => assertTransition(from, to)).not.toThrow();
  });

  // Every other pair of statuses, including repeating the same status, is rejected.
  const illegal = ALL_STATUSES.flatMap((from) => ALL_STATUSES.map((to) => [from, to])).filter(
    ([from, to]) => !legal.some(([f, t]) => f === from && t === to),
  );

  test.each(illegal)('%s -> %s is rejected', (from, to) => {
    expect(canTransition(from, to)).toBe(false);
    expect(() => assertTransition(from, to)).toThrow(expect.objectContaining({ code: 'INVALID_TRANSITION', status: 409 }));
  });

  test('allowed actions follow the rules', () => {
    expect(allowedActions('received')).toEqual(['start', 'cancel']);
    expect(allowedActions('preparing')).toEqual(['ready']);
    expect(allowedActions('ready')).toEqual(['pickup']);
    expect(allowedActions('picked_up')).toEqual([]);
    expect(allowedActions('cancelled')).toEqual([]);
  });
});

describe('orderModule.changeStatus', () => {
  function setup(status) {
    const repository = createFakeOrderRepository([makeOrder(1, status)]);
    return { repository, orders: createOrderModule(repository) };
  }

  test.each([
    ['start', 'received', 'preparing'],
    ['cancel', 'received', 'cancelled'],
    ['ready', 'preparing', 'ready'],
    ['pickup', 'ready', 'picked_up'],
  ])('%s moves %s -> %s', async (action, from, to) => {
    const { repository, orders } = setup(from);

    const result = await orders.changeStatus(1, action);

    expect(result.status).toBe(to);
    expect(repository.orders[0].status).toBe(to);
  });

  test('skipping a step is rejected (received cannot jump to ready)', async () => {
    const { repository, orders } = setup('received');

    await expect(orders.changeStatus(1, 'ready')).rejects.toMatchObject({ code: 'INVALID_TRANSITION' });
    expect(repository.orders[0].status).toBe('received');
  });

  test('starting an order that is already preparing is an error, not a silent success', async () => {
    const { repository, orders } = setup('preparing');

    await expect(orders.changeStatus(1, 'start')).rejects.toMatchObject({ code: 'INVALID_TRANSITION', status: 409 });
    expect(repository.orders[0].status).toBe('preparing');
  });

  test.each(['start', 'ready', 'pickup', 'cancel'])('a cancelled order rejects %s', async (action) => {
    const { orders } = setup('cancelled');
    await expect(orders.changeStatus(1, action)).rejects.toMatchObject({ code: 'INVALID_TRANSITION' });
  });

  test.each(['start', 'ready', 'pickup', 'cancel'])('a picked-up order rejects %s', async (action) => {
    const { orders } = setup('picked_up');
    await expect(orders.changeStatus(1, action)).rejects.toMatchObject({ code: 'INVALID_TRANSITION' });
  });

  test('a preparing order cannot be cancelled', async () => {
    const { orders } = setup('preparing');
    await expect(orders.changeStatus(1, 'cancel')).rejects.toMatchObject({ code: 'INVALID_TRANSITION' });
  });

  test('an unknown order id returns ORDER_NOT_FOUND', async () => {
    const { orders } = setup('received');
    await expect(orders.changeStatus(999, 'start')).rejects.toMatchObject({ code: 'ORDER_NOT_FOUND', status: 404 });
    await expect(orders.changeStatus(NaN, 'start')).rejects.toMatchObject({ code: 'ORDER_NOT_FOUND' });
  });

  test('rejects when the status changed between the read and the write', async () => {
    const { repository, orders } = setup('received');
    // Simulate another request winning the race: the conditional update finds nothing to change.
    repository.updateStatus = async () => false;

    await expect(orders.changeStatus(1, 'start')).rejects.toMatchObject({ code: 'INVALID_TRANSITION' });
  });
});

describe('orderModule.getQueue', () => {
  const repository = createFakeOrderRepository([
    makeOrder(1, 'received'),
    makeOrder(2, 'preparing'),
    makeOrder(3, 'ready'),
    makeOrder(4, 'picked_up'),
    makeOrder(5, 'cancelled'),
  ]);
  const orders = createOrderModule(repository);

  test('the default queue only has received and preparing orders', async () => {
    const queue = await orders.getQueue({ now: NOW });
    expect(queue.map((o) => o.id).sort()).toEqual([1, 2]);
  });

  test('an order disappears from the default queue once cancelled or picked up', async () => {
    const repo = createFakeOrderRepository([makeOrder(1, 'received'), makeOrder(2, 'ready')]);
    const module = createOrderModule(repo);

    await module.changeStatus(1, 'cancel');
    await module.changeStatus(2, 'pickup');

    expect(await module.getQueue({ now: NOW })).toEqual([]);
  });

  test('filters by status', async () => {
    const queue = await orders.getQueue({ status: 'preparing', now: NOW });
    expect(queue.map((o) => o.id)).toEqual([2]);
  });

  test('each order carries its score and allowed actions', async () => {
    const [first] = await orders.getQueue({ status: 'received', now: NOW });
    expect(first.score).toBe(30);
    expect(first.minutes_waiting).toBe(0);
    expect(first.allowed_actions).toEqual(['start', 'cancel']);
  });

  test.each(['ready', 'cancelled', 'bogus'])('rejects status filter "%s"', async (status) => {
    await expect(orders.getQueue({ status, now: NOW })).rejects.toMatchObject({ code: 'INVALID_STATUS_FILTER', status: 400 });
  });
});

const { createOrderModule } = require('../src/modules/orderModule');
const { createFakeOrderRepository } = require('./fakeOrderRepository');

const NOW = new Date('2026-06-15T12:00:00Z');
const MENU_ITEM_IDS = [1, 2];

function validInput(overrides = {}) {
  return {
    customer_name: 'Marta',
    type: 'takeout',
    is_vip: false,
    promised_at: '2026-06-15T12:30:00Z',
    items: [{ menu_item_id: 1, quantity: 2 }],
    ...overrides,
  };
}

function setup() {
  const repository = createFakeOrderRepository([], MENU_ITEM_IDS);
  return { repository, orders: createOrderModule(repository) };
}

describe('orderModule.createOrder', () => {
  test('creates a received order placed at now', async () => {
    const { repository, orders } = setup();

    const order = await orders.createOrder(validInput(), NOW);

    expect(order).toMatchObject({ id: 1, status: 'received', placed_at: NOW, customer_name: 'Marta' });
    expect(repository.orders).toHaveLength(1);
  });

  test.each([
    ['empty items', { items: [] }, 'items must be a non-empty array'],
    ['missing items', { items: undefined }, 'items must be a non-empty array'],
    ['zero quantity', { items: [{ menu_item_id: 1, quantity: 0 }] }, 'items[0].quantity must be a positive integer'],
    ['decimal quantity', { items: [{ menu_item_id: 1, quantity: 1.5 }] }, 'items[0].quantity must be a positive integer'],
    ['text menu_item_id', { items: [{ menu_item_id: '1', quantity: 1 }] }, 'items[0].menu_item_id must be a positive integer'],
    ['empty customer_name', { customer_name: '  ' }, 'customer_name must be a non-empty string'],
    ['unknown type', { type: 'drive_thru' }, 'type must be one of'],
    ['bad promised_at', { promised_at: 'tomorrow' }, 'promised_at must be an ISO 8601 timestamp'],
  ])('rejects %s with VALIDATION_ERROR', async (_label, overrides, message) => {
    const { repository, orders } = setup();

    const error = await orders.createOrder(validInput(overrides), NOW).catch((e) => e);

    expect(error).toMatchObject({ status: 400, code: 'VALIDATION_ERROR' });
    expect(error.message).toContain(message);
    expect(repository.orders).toHaveLength(0);
  });

  test('rejects a menu_item_id that does not exist', async () => {
    const { repository, orders } = setup();

    const input = validInput({ items: [{ menu_item_id: 1, quantity: 1 }, { menu_item_id: 99, quantity: 1 }] });

    await expect(orders.createOrder(input, NOW)).rejects.toMatchObject({
      code: 'VALIDATION_ERROR',
      message: 'menu_item_id does not exist: 99',
    });
    expect(repository.orders).toHaveLength(0);
  });
});

