import Button from '@mui/material/Button';
import Chip from '@mui/material/Chip';
import Stack from '@mui/material/Stack';
import Table from '@mui/material/Table';
import TableBody from '@mui/material/TableBody';
import TableCell from '@mui/material/TableCell';
import TableContainer from '@mui/material/TableContainer';
import TableHead from '@mui/material/TableHead';
import TableRow from '@mui/material/TableRow';
import Typography from '@mui/material/Typography';
import type { OrderAction, OrderStatus, OrderType, QueueOrder } from '../types';

// Display labels only. Which actions an order has comes from the API (`allowed_actions`),
// so the UI never decides what a legal status change is.
const ACTION_LABELS: Record<OrderAction, string> = {
  start: 'Start',
  ready: 'Mark ready',
  pickup: 'Picked up',
  cancel: 'Cancel',
};

const TYPE_LABELS: Record<OrderType, string> = {
  dine_in: 'Dine-in',
  takeout: 'Takeout',
  delivery: 'Delivery',
};

const STATUS_COLORS: Record<OrderStatus, 'default' | 'info' | 'warning' | 'success' | 'error'> = {
  received: 'info',
  preparing: 'warning',
  ready: 'success',
  picked_up: 'default',
  cancelled: 'error',
};

function formatTime(iso: string | null): string {
  if (!iso) return '—';
  return new Date(iso).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
}

function formatItems(order: QueueOrder): string {
  return order.items.map((item) => `${item.quantity}× ${item.name}`).join(', ');
}

interface QueueTableProps {
  orders: QueueOrder[];
  busyOrderId: number | null;
  onAction: (order: QueueOrder, action: OrderAction) => void;
}

export function QueueTable({ orders, busyOrderId, onAction }: QueueTableProps) {
  return (
    <TableContainer>
      <Table size="small" stickyHeader aria-label="Order queue">
        <TableHead>
          <TableRow>
            <TableCell align="right">Score</TableCell>
            <TableCell>Customer</TableCell>
            <TableCell>Type</TableCell>
            <TableCell>Items</TableCell>
            <TableCell align="right">Waiting</TableCell>
            <TableCell>Promised</TableCell>
            <TableCell>VIP</TableCell>
            <TableCell>Status</TableCell>
            <TableCell>Actions</TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {orders.length === 0 ? (
            <TableRow>
              <TableCell colSpan={9} align="center" sx={{ py: 6 }}>
                <Typography color="text.secondary">No orders in the queue</Typography>
              </TableCell>
            </TableRow>
          ) : (
            orders.map((order) => (
              <TableRow key={order.id} hover>
                <TableCell align="right" sx={{ fontWeight: 600 }}>
                  {order.score}
                </TableCell>
                <TableCell>{order.customer_name}</TableCell>
                <TableCell>{TYPE_LABELS[order.type]}</TableCell>
                <TableCell>{formatItems(order)}</TableCell>
                <TableCell align="right">{order.minutes_waiting} min</TableCell>
                <TableCell>{formatTime(order.promised_at)}</TableCell>
                <TableCell>{order.is_vip && <Chip label="VIP" color="secondary" size="small" />}</TableCell>
                <TableCell>
                  <Chip label={order.status} color={STATUS_COLORS[order.status]} size="small" variant="outlined" />
                </TableCell>
                <TableCell>
                  <Stack direction="row" spacing={1}>
                    {order.allowed_actions.map((action) => (
                      <Button
                        key={action}
                        size="small"
                        variant={action === 'cancel' ? 'outlined' : 'contained'}
                        color={action === 'cancel' ? 'error' : 'primary'}
                        disabled={busyOrderId === order.id}
                        onClick={() => onAction(order, action)}
                      >
                        {ACTION_LABELS[action]}
                      </Button>
                    ))}
                  </Stack>
                </TableCell>
              </TableRow>
            ))
          )}
        </TableBody>
      </Table>
    </TableContainer>
  );
}

import { useCallback, useEffect, useState } from 'react';
import Alert from '@mui/material/Alert';
import LinearProgress from '@mui/material/LinearProgress';
import Paper from '@mui/material/Paper';
import Stack from '@mui/material/Stack';
import ToggleButton from '@mui/material/ToggleButton';
import ToggleButtonGroup from '@mui/material/ToggleButtonGroup';
import Typography from '@mui/material/Typography';
import { ApiError, fetchQueue, runOrderAction } from '../api';
import type { OrderAction, QueueFilter, QueueOrder } from '../types';
import { QueueTable } from './QueueTable';

// Scores depend on the clock, so the queue is re-fetched periodically.
const REFRESH_MS = 30_000;

function errorMessage(error: unknown): string {
  if (error instanceof ApiError) return `${error.code}: ${error.message}`;
  return 'Unexpected error';
}

export function KitchenDisplay() {
  const [filter, setFilter] = useState<QueueFilter>('active');
  const [orders, setOrders] = useState<QueueOrder[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [busyOrderId, setBusyOrderId] = useState<number | null>(null);

  const loadQueue = useCallback(async () => {
    try {
      setOrders(await fetchQueue(filter));
    } catch (e) {
      setError(errorMessage(e));
    } finally {
      setLoading(false);
    }
  }, [filter]);

  useEffect(() => {
    setLoading(true);
    loadQueue();
    const timer = setInterval(loadQueue, REFRESH_MS);
    return () => clearInterval(timer);
  }, [loadQueue]);

  async function handleAction(order: QueueOrder, action: OrderAction) {
    setBusyOrderId(order.id);
    setError(null);
    try {
      await runOrderAction(order.id, action);
    } catch (e) {
      setError(errorMessage(e));
    } finally {
      setBusyOrderId(null);
      // Always reload: the order moved, or someone else changed it and the screen is stale.
      await loadQueue();
    }
  }

  return (
    <Stack spacing={2}>
      <Stack direction="row" alignItems="center" justifyContent="space-between">
        <Typography variant="subtitle1" color="text.secondary">
          {orders.length} order{orders.length === 1 ? '' : 's'} · sorted by priority (highest first)
        </Typography>
        <ToggleButtonGroup
          size="small"
          exclusive
          value={filter}
          onChange={(_event, value: QueueFilter | null) => value && setFilter(value)}
          aria-label="Filter by status"
        >
          <ToggleButton value="active">Active</ToggleButton>
          <ToggleButton value="received">Received</ToggleButton>
          <ToggleButton value="preparing">Preparing</ToggleButton>
        </ToggleButtonGroup>
      </Stack>

      {error && (
        <Alert severity="error" onClose={() => setError(null)}>
          {error}
        </Alert>
      )}

      <Paper variant="outlined">
        {loading && <LinearProgress />}
        <QueueTable orders={orders} busyOrderId={busyOrderId} onAction={handleAction} />
      </Paper>
    </Stack>
  );
}

