// Shapes returned by the API (see api/src/modules/orderModule.js).

export type OrderType = 'dine_in' | 'takeout' | 'delivery';
export type OrderStatus = 'received' | 'preparing' | 'ready' | 'picked_up' | 'cancelled';
export type OrderAction = 'start' | 'ready' | 'pickup' | 'cancel';

// 'active' = the default queue (no status filter sent to the API)
export type QueueFilter = 'active' | 'received' | 'preparing';

export interface OrderItem {
  menu_item_id: number;
  name: string;
  quantity: number;
}

export interface QueueOrder {
  id: number;
  customer_name: string;
  type: OrderType;
  is_vip: boolean;
  status: OrderStatus;
  placed_at: string;
  promised_at: string | null;
  items: OrderItem[];
  score: number;
  minutes_waiting: number;
  allowed_actions: OrderAction[];
}

import type { OrderAction, QueueFilter, QueueOrder } from './types';

export class ApiError extends Error {
  code: string;

  constructor(code: string, message: string) {
    super(message);
    this.code = code;
  }
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  let response: Response;
  try {
    response = await fetch(`/api${path}`, init);
  } catch {
    throw new ApiError('NETWORK_ERROR', 'Could not reach the API');
  }

  const body = await response.json().catch(() => null);
  if (!response.ok) {
    throw new ApiError(body?.error?.code ?? 'HTTP_ERROR', body?.error?.message ?? `Request failed (${response.status})`);
  }
  return body as T;
}

export async function fetchQueue(filter: QueueFilter): Promise<QueueOrder[]> {
  const query = filter === 'active' ? '' : `?status=${filter}`;
  const { orders } = await request<{ orders: QueueOrder[] }>(`/orders/queue${query}`);
  return orders;
}

export async function runOrderAction(orderId: number, action: OrderAction): Promise<void> {
  await request(`/orders/${orderId}/${action}`, { method: 'POST' });
}

