import { useEffect, useState, type FormEvent } from 'react';
import Alert from '@mui/material/Alert';
import Button from '@mui/material/Button';
import Checkbox from '@mui/material/Checkbox';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import FormControlLabel from '@mui/material/FormControlLabel';
import Stack from '@mui/material/Stack';
import TextField from '@mui/material/TextField';
import Typography from '@mui/material/Typography';
import { ApiError, createOrder, fetchMenuItems } from '../api';
import type { MenuItemOption, NewOrderInput, OrderType, QueueOrder } from '../types';

// Form state keeps raw input strings; the API is the one that validates them.
interface ItemRow {
  menuItemId: string;
  quantity: string;
}

const EMPTY_ROW: ItemRow = { menuItemId: '', quantity: '1' };

function toPayload(
  customerName: string,
  type: OrderType,
  isVip: boolean,
  promisedInMinutes: string,
  items: ItemRow[],
): NewOrderInput {
  return {
    customer_name: customerName,
    type,
    is_vip: isVip,
    promised_at:
      promisedInMinutes.trim() === ''
        ? null
        : new Date(Date.now() + Number(promisedInMinutes) * 60_000).toISOString(),
    items: items.map((row) => ({ menu_item_id: Number(row.menuItemId), quantity: Number(row.quantity) })),
  };
}

interface NewOrderDialogProps {
  open: boolean;
  onClose: () => void;
  onCreated: (order: QueueOrder) => void;
}

export function NewOrderDialog({ open, onClose, onCreated }: NewOrderDialogProps) {
  const [menuItems, setMenuItems] = useState<MenuItemOption[]>([]);
  const [customerName, setCustomerName] = useState('');
  const [type, setType] = useState<OrderType>('dine_in');
  const [isVip, setIsVip] = useState(false);
  const [promisedInMinutes, setPromisedInMinutes] = useState('');
  const [items, setItems] = useState<ItemRow[]>([EMPTY_ROW]);
  const [error, setError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  // Fresh, empty form every time the dialog opens.
  useEffect(() => {
    if (!open) return;
    setCustomerName('');
    setType('dine_in');
    setIsVip(false);
    setPromisedInMinutes('');
    setItems([EMPTY_ROW]);
    setError(null);
    fetchMenuItems()
      .then(setMenuItems)
      .catch(() => setError('Could not load the menu'));
  }, [open]);

  function updateRow(index: number, change: Partial<ItemRow>) {
    setItems((rows) => rows.map((row, i) => (i === index ? { ...row, ...change } : row)));
  }

  async function handleSubmit(event: FormEvent) {
    event.preventDefault();
    setSubmitting(true);
    setError(null);
    try {
      const order = await createOrder(toPayload(customerName, type, isVip, promisedInMinutes, items));
      onCreated(order);
    } catch (e) {
      setError(e instanceof ApiError ? `${e.code}: ${e.message}` : 'Unexpected error');
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <Dialog open={open} onClose={onClose} fullWidth maxWidth="sm">
      <form onSubmit={handleSubmit} noValidate>
        <DialogTitle>New order</DialogTitle>
        <DialogContent>
          <Stack spacing={2} sx={{ pt: 1 }}>
            {error && <Alert severity="error">{error}</Alert>}

            <TextField
              id="new-order-customer"
              label="Customer name"
              size="small"
              value={customerName}
              onChange={(e) => setCustomerName(e.target.value)}
              autoFocus
            />

            <Stack direction="row" spacing={2} alignItems="center">
              <TextField
                id="new-order-type"
                label="Type"
                size="small"
                select
                slotProps={{ select: { native: true } }}
                value={type}
                onChange={(e) => setType(e.target.value as OrderType)}
                sx={{ minWidth: 140 }}
              >
                <option value="dine_in">Dine-in</option>
                <option value="takeout">Takeout</option>
                <option value="delivery">Delivery</option>
              </TextField>
              <TextField
                id="new-order-promised"
                label="Promised in (minutes)"
                size="small"
                type="number"
                value={promisedInMinutes}
                onChange={(e) => setPromisedInMinutes(e.target.value)}
                helperText="Leave empty for no promised time"
              />
              <FormControlLabel
                control={<Checkbox checked={isVip} onChange={(e) => setIsVip(e.target.checked)} />}
                label="VIP"
              />
            </Stack>

            <Typography variant="subtitle2">Items</Typography>
            {items.map((row, index) => (
              <Stack key={index} direction="row" spacing={1} alignItems="center">
                <TextField
                  id={`new-order-item-${index}`}
                  label="Menu item"
                  size="small"
                  select
                  slotProps={{ select: { native: true } }}
                  value={row.menuItemId}
                  onChange={(e) => updateRow(index, { menuItemId: e.target.value })}
                  sx={{ flex: 1 }}
                >
                  <option value="">Choose…</option>
                  {menuItems.map((item) => (
                    <option key={item.id} value={item.id}>
                      {item.name}
                    </option>
                  ))}
                </TextField>
                <TextField
                  id={`new-order-quantity-${index}`}
                  label="Quantity"
                  size="small"
                  type="number"
                  value={row.quantity}
                  onChange={(e) => updateRow(index, { quantity: e.target.value })}
                  sx={{ width: 100 }}
                />
                <Button
                  size="small"
                  color="inherit"
                  disabled={items.length === 1}
                  onClick={() => setItems((rows) => rows.filter((_, i) => i !== index))}
                >
                  Remove
                </Button>
              </Stack>
            ))}
            <Button size="small" onClick={() => setItems((rows) => [...rows, EMPTY_ROW])} sx={{ alignSelf: 'flex-start' }}>
              Add item
            </Button>
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={onClose}>Close</Button>
          <Button type="submit" variant="contained" disabled={submitting}>
            Create order
          </Button>
        </DialogActions>
      </form>
    </Dialog>
  );
}

import { useCallback, useEffect, useRef, useState } from 'react';
import Alert from '@mui/material/Alert';
import Fab from '@mui/material/Fab';
import LinearProgress from '@mui/material/LinearProgress';
import Paper from '@mui/material/Paper';
import Snackbar from '@mui/material/Snackbar';
import Stack from '@mui/material/Stack';
import SvgIcon from '@mui/material/SvgIcon';
import ToggleButton from '@mui/material/ToggleButton';
import ToggleButtonGroup from '@mui/material/ToggleButtonGroup';
import Typography from '@mui/material/Typography';
import { ApiError, fetchQueue, runOrderAction } from '../api';
import type { OrderAction, QueueFilter, QueueOrder } from '../types';
import { NewOrderDialog } from './NewOrderDialog';
import { QueueTable } from './QueueTable';

// Background refresh: picks up new orders from other sources and keeps scores current.
export const REFRESH_MS = 5_000;

function errorMessage(error: unknown): string {
  if (error instanceof ApiError) return `${error.code}: ${error.message}`;
  return 'Unexpected error';
}

function formatClock(date: Date): string {
  return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
}

export function KitchenDisplay() {
  const [filter, setFilter] = useState<QueueFilter>('active');
  const [orders, setOrders] = useState<QueueOrder[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [busyOrderId, setBusyOrderId] = useState<number | null>(null);
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [notice, setNotice] = useState<string | null>(null);

  // Only the most recent request may update the table, so a slow response for an
  // old filter cannot overwrite a newer one.
  const latestRequest = useRef(0);

  const loadQueue = useCallback(async () => {
    const requestId = ++latestRequest.current;
    try {
      const result = await fetchQueue(filter);
      if (requestId !== latestRequest.current) return;
      setOrders(result);
      setLastUpdated(new Date());
    } catch (e) {
      if (requestId === latestRequest.current) setError(errorMessage(e));
    } finally {
      if (requestId === latestRequest.current) setLoading(false);
    }
  }, [filter]);

  useEffect(() => {
    setLoading(true);
    loadQueue();
    // Quiet refresh (no progress bar); skipped while the browser tab is hidden.
    const timer = setInterval(() => {
      if (!document.hidden) loadQueue();
    }, REFRESH_MS);
    return () => clearInterval(timer);
  }, [loadQueue]);

  async function handleAction(order: QueueOrder, action: OrderAction) {
    setBusyOrderId(order.id);
    setError(null);
    try {
      await runOrderAction(order.id, action);
    } catch (e) {
      setError(errorMessage(e));
    } finally {
      setBusyOrderId(null);
      // Always reload: the order moved, or someone else changed it and the screen is stale.
      await loadQueue();
    }
  }

  function handleCreated(order: QueueOrder) {
    setDialogOpen(false);
    setNotice(`Order #${order.id} for ${order.customer_name} created`);
    loadQueue();
  }

  return (
    <Stack spacing={2}>
      <Stack direction="row" alignItems="center" justifyContent="space-between">
        <Typography variant="subtitle1" color="text.secondary">
          {orders.length} order{orders.length === 1 ? '' : 's'} · sorted by priority (highest first)
          {lastUpdated && ` · auto-refresh every ${REFRESH_MS / 1000}s, updated ${formatClock(lastUpdated)}`}
        </Typography>
        <ToggleButtonGroup
          size="small"
          exclusive
          value={filter}
          onChange={(_event, value: QueueFilter | null) => value && setFilter(value)}
          aria-label="Filter by status"
        >
          <ToggleButton value="active">Active</ToggleButton>
          <ToggleButton value="received">Received</ToggleButton>
          <ToggleButton value="preparing">Preparing</ToggleButton>
        </ToggleButtonGroup>
      </Stack>

      {error && (
        <Alert severity="error" onClose={() => setError(null)}>
          {error}
        </Alert>
      )}

      <Paper variant="outlined">
        {loading && <LinearProgress />}
        <QueueTable orders={orders} busyOrderId={busyOrderId} onAction={handleAction} />
      </Paper>

      <Fab
        color="primary"
        aria-label="New order"
        onClick={() => setDialogOpen(true)}
        sx={{ position: 'fixed', right: 24, bottom: 24 }}
      >
        <SvgIcon>
          <path d="M19 13h-6v6h-2v-6H5v-2h6V5h2v6h6v2z" />
        </SvgIcon>
      </Fab>

      <NewOrderDialog open={dialogOpen} onClose={() => setDialogOpen(false)} onCreated={handleCreated} />

      <Snackbar
        open={notice !== null}
        autoHideDuration={4000}
        onClose={() => setNotice(null)}
        message={notice}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'left' }}
      />
    </Stack>
  );
}

